window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4b2ddec02d2ed0a2"]={"versions": [{"id": "FIG-4b2ddec02d2ed0a2", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Classic Platform (Metamodell-Ausschnitt BSWMD / BswModuleDescription). Das Diagramm spezifiziert die Metaklasse <code>BswModuleEntry</code> zur formalen Deklaration von Funktionsschnittstellen, API-Einsprungpunkten und Callback-Routinen von Basissoftware-Modulen sowie deren Einbettung in das übergeordnete <code>ServiceProcessTask</code>- und Datendefinitions-Modell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>BswModuleEntry</strong> (Spezialisierung von <code>ServiceProcessTask::SwService</code>):</li>\n<li>Attribute:</li>\n<li><code>callType: BswCallType</code></li>\n<li><code>executionContext: BswExecutionContext</code></li>\n<li><code>isSynchronous: Boolean</code></li>\n<li><code>serviceId: Int</code></li>\n<li><strong>Enumerationen</strong>:</li>\n<li><code>BswCallType</code>: Literale <code>regular</code>, <code>callback</code>, <code>interrupt</code>, <code>scheduled</code></li>\n<li><code>BswExecutionContext</code>: Literale <code>task</code>, <code>interrupt</code>, <code>unspecified</code></li>\n<li><strong>ServiceProcessTask::SwService</strong> (Stereotyp <code>ARElement</code>):</li>\n<li>Komposition <code>+swServiceProps</code> (0..1) zu <code>ServiceProcessTask::SwServiceProps</code></li>\n<li>Komposition <code>+swServiceReturn</code> (0..1) zu <code>DataDefProperties::SwDataDefProps</code></li>\n<li>Komposition <code>+swServiceArg</code> (0..* {ordered}) zu <code>ServiceProcessTask::SwServiceArg</code></li>\n<li><strong>ServiceProcessTask::SwServiceProps</strong>:</li>\n<li>Attribute: <code>swImplPolicy: SwServiceImplPolicyEnum [0..1]</code>, <code>swServiceRecursive: String [0..1]</code>, <code>swServiceReentrance: SwServiceReentranceEnum [0..1]</code></li>\n<li><strong>ServiceProcessTask::SwServiceArg</strong> (Stereotyp <code>Identifiable</code>):</li>\n<li>Komposition <code>+swDataDefProps</code> (0..1) zu <code>DataDefProperties::SwDataDefProps</code></li>\n<li><strong>DataDefProperties::SwDataDefProps</strong> (Stereotyp <code>IsSyscond</code>):</li>\n<li>Attribute: <code>displayFormat: DisplayFormatString [0..1]</code>, <code>swAliasName: String [0..1]</code>, <code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>, <code>swCalprmNoEffectValue: String [0..1]</code>, <code>swImplPolicy: SwImplPolicyEnum [0..1]</code>, <code>swIntendedResolution: NumericalValue [0..1]</code>, <code>swInterpolationMethod: String [0..1]</code>, <code>swIsVirtual: Boolean [0..1]</code>, <code>swVariableAccessImplPolicy: SwVariableAccessImplPolicyEnum [0..1]</code>, <code>swVarNotAvlValue: String [0..1]</code></li>\n<li>Assoziation <code>+baseType</code> (0..1) zu <code>BaseTypes::SwBaseType</code> (Stereotyp <code>BaseType</code>)</li>\n<li>Assoziation <code>+swClass</code> (0..1) zu <code>SwClass::SwClass</code> (Stereotyp <code>ARElement</code>), Gegenrichtung aggregiert <code>+swDataDefProps</code> (0..1)</li>\n<li>Assoziation / Komposition <code>+swPointer</code> (0..1) zu <code>DataDefProperties::SwPointer</code>, Gegenrichtung aggregiert <code>+swDataDefProps</code> (0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Interaktionsdarstellung. Die Attribute definieren das Laufzeitverhalten deklarativ: <code>callType</code> determiniert den Aufrufmodus (zyklisch, Callback, ISR, regulär), <code>executionContext</code> den Ausführungskontext (Task, Interrupt), <code>isSynchronous</code> das Blockierverhalten sowie <code>swServiceReentrance</code> und <code>swServiceRecursive</code> die Reentrancy- und Rekursionseigenschaften bei nebenläufiger Ausführung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für BSW-Modulbeschreibungen (BSWMD-Dateien). Die Definition von <code>BswModuleEntry</code> ist verpflichtend für die Generierung von BSW-Schedulern, RTE-BSW-Schnittstellen und Modul-Headern. Die Attribute steuern Signaturprüfungen, Parameterübergaben (<code>swServiceArg</code>, <code>swServiceReturn</code>), Datentypspezifikationen über <code>SwDataDefProps</code> und <code>SwBaseType</code> sowie die Konfiguration des Betriebssystems bezüglich Task- und ISR-Kontexten.</p>"}, {"id": "FIG-6cac80cfc422700c", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Classic Platform (Metamodell-Ausschnitt BSWMD / BswModuleDescription). Das Diagramm spezifiziert die Metaklasse <code>BswModuleEntry</code> zur formalen Deklaration von Funktionsschnittstellen, API-Einsprungpunkten und Callback-Routinen von Basissoftware-Modulen sowie deren Einbettung in das übergeordnete <code>ServiceProcessTask</code>- und Datendefinitions-Modell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>BswModuleEntry</strong> (Spezialisierung von <code>ServiceProcessTask::SwService</code>):</li>\n<li>Attribute:</li>\n<li><code>callType: BswCallType</code></li>\n<li><code>executionContext: BswExecutionContext</code></li>\n<li><code>isSynchronous: Boolean</code></li>\n<li><code>serviceId: Int</code></li>\n<li><strong>Enumerationen</strong>:</li>\n<li><code>BswCallType</code>: Literale <code>regular</code>, <code>callback</code>, <code>interrupt</code>, <code>scheduled</code></li>\n<li><code>BswExecutionContext</code>: Literale <code>task</code>, <code>interrupt</code>, <code>unspecified</code></li>\n<li><strong>ServiceProcessTask::SwService</strong> (Stereotyp <code>ARElement</code>):</li>\n<li>Komposition <code>+swServiceProps</code> (0..1) zu <code>ServiceProcessTask::SwServiceProps</code></li>\n<li>Komposition <code>+swServiceReturn</code> (0..1) zu <code>DataDefProperties::SwDataDefProps</code></li>\n<li>Komposition <code>+swServiceArg</code> (0..* {ordered}) zu <code>ServiceProcessTask::SwServiceArg</code></li>\n<li><strong>ServiceProcessTask::SwServiceProps</strong>:</li>\n<li>Attribute: <code>swImplPolicy: SwServiceImplPolicyEnum [0..1]</code>, <code>swServiceRecursive: String [0..1]</code>, <code>swServiceReentrance: SwServiceReentranceEnum [0..1]</code></li>\n<li><strong>ServiceProcessTask::SwServiceArg</strong> (Stereotyp <code>Identifiable</code>):</li>\n<li>Komposition <code>+swDataDefProps</code> (0..1) zu <code>DataDefProperties::SwDataDefProps</code></li>\n<li><strong>DataDefProperties::SwDataDefProps</strong> (Stereotyp <code>IsSyscond</code>):</li>\n<li>Attribute: <code>displayFormat: DisplayFormatString [0..1]</code>, <code>swAliasName: String [0..1]</code>, <code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>, <code>swCalprmNoEffectValue: String [0..1]</code>, <code>swImplPolicy: SwImplPolicyEnum [0..1]</code>, <code>swIntendedResolution: NumericalValue [0..1]</code>, <code>swInterpolationMethod: String [0..1]</code>, <code>swIsVirtual: Boolean [0..1]</code>, <code>swVariableAccessImplPolicy: SwVariableAccessImplPolicyEnum [0..1]</code>, <code>swVarNotAvlValue: String [0..1]</code></li>\n<li>Assoziation <code>+baseType</code> (0..1) zu <code>BaseTypes::SwBaseType</code> (Stereotyp <code>BaseType</code>)</li>\n<li>Assoziation <code>+swClass</code> (0..1) zu <code>SwClass::SwClass</code> (Stereotyp <code>ARElement</code>), Gegenrichtung aggregiert <code>+swDataDefProps</code> (0..1)</li>\n<li>Assoziation / Komposition <code>+swPointer</code> (0..1) zu <code>DataDefProperties::SwPointer</code>, Gegenrichtung aggregiert <code>+swDataDefProps</code> (0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Interaktionsdarstellung. Die Attribute definieren das Laufzeitverhalten deklarativ: <code>callType</code> determiniert den Aufrufmodus (zyklisch, Callback, ISR, regulär), <code>executionContext</code> den Ausführungskontext (Task, Interrupt), <code>isSynchronous</code> das Blockierverhalten sowie <code>swServiceReentrance</code> und <code>swServiceRecursive</code> die Reentrancy- und Rekursionseigenschaften bei nebenläufiger Ausführung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für BSW-Modulbeschreibungen (BSWMD-Dateien). Die Definition von <code>BswModuleEntry</code> ist verpflichtend für die Generierung von BSW-Schedulern, RTE-BSW-Schnittstellen und Modul-Headern. Die Attribute steuern Signaturprüfungen, Parameterübergaben (<code>swServiceArg</code>, <code>swServiceReturn</code>), Datentypspezifikationen über <code>SwDataDefProps</code> und <code>SwBaseType</code> sowie die Konfiguration des Betriebssystems bezüglich Task- und ISR-Kontexten.</p>"}, {"id": "FIG-9c77d80b64fcc564", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Classic Platform (Metamodell-Ausschnitt BSWMD / BswModuleDescription). Das Diagramm spezifiziert die Metaklasse <code>BswModuleEntry</code> zur formalen Deklaration von Funktionsschnittstellen, API-Einsprungpunkten und Callback-Routinen von Basissoftware-Modulen sowie deren Einbettung in das übergeordnete <code>ServiceProcessTask</code>- und Datendefinitions-Modell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>BswModuleEntry</strong> (Spezialisierung von <code>ServiceProcessTask::SwService</code>):</li>\n<li>Attribute:</li>\n<li><code>callType :BswCallType</code></li>\n<li><code>executionContext :BswExecutionContext</code></li>\n<li><code>isSynchronous :Boolean</code></li>\n<li><code>serviceId :Integer</code></li>\n<li><strong>Enumerationen</strong>:</li>\n<li><code>BswCallType</code>: Literale <code>regular</code>, <code>callback</code>, <code>interrupt</code>, <code>scheduled</code></li>\n<li><code>BswExecutionContext</code>: Literale <code>task</code>, <code>interrupt</code>, <code>unspecified</code></li>\n<li><strong>ServiceProcessTask::SwService</strong> (Stereotyp <code>ARElement</code>):</li>\n<li>Komposition <code>+swServiceProps</code> (0..1) zu <code>ServiceProcessTask::SwServiceProps</code></li>\n<li>Komposition <code>+swServiceReturn</code> (0..1) zu <code>DataDefProperties::SwDataDefProps</code></li>\n<li>Komposition <code>+swServiceArg</code> (0..* {ordered}) zu <code>ServiceProcessTask::SwServiceArg</code></li>\n<li><strong>ServiceProcessTask::SwServiceProps</strong>:</li>\n<li>Attribute: <code>swImplPolicy :SwServiceImplPolicyEnum [0..1]</code>, <code>swServiceReentrance :SwServiceReentranceEnum [0..1]</code></li>\n<li><strong>ServiceProcessTask::SwServiceArg</strong> (Stereotyp <code>Identifiable</code>):</li>\n<li>Komposition <code>+swDataDefProps</code> (0..1) zu <code>DataDefProperties::SwDataDefProps</code></li>\n<li><strong>DataDefProperties::SwDataDefProps</strong> (Stereotyp <code>IsSyscond</code>):</li>\n<li>Attribute: <code>displayFormat :DisplayFormatString [0..1]</code>, <code>swCalibrationAccess :SwCalibrationAccessEnum [0..1]</code>, <code>swImplPolicy :SwImplPolicyEnum [0..1]</code>, <code>swVariableAccessImplPolicy :SwVariableAccessImplPolicyEnum [0..1]</code></li>\n<li>Assoziation <code>+baseType</code> (0..1) zu <code>BaseTypes::SwBaseType</code> (Stereotyp <code>BaseType</code>)</li>\n<li>Assoziation / Komposition <code>+swPointer</code> (0..1) zu <code>DataDefProperties::SwPointer</code>, Gegenrichtung aggregiert <code>+swDataDefProps</code> (0..1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Interaktionsdarstellung. Die Attribute definieren das Laufzeitverhalten deklarativ: <code>callType</code> determiniert den Aufrufmodus (zyklisch, Callback, ISR, regulär), <code>executionContext</code> den Ausführungskontext (Task, Interrupt), <code>isSynchronous</code> das Blockierverhalten sowie <code>swServiceReentrance</code> die Wiedereintrittsfähigkeit bei nebenläufiger Ausführung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für BSW-Modulbeschreibungen (BSWMD-Dateien). Die Definition von <code>BswModuleEntry</code> ist verpflichtend für die Generierung von BSW-Schedulern, RTE-BSW-Schnittstellen und Modul-Headern. Die Attribute steuern Signaturprüfungen, Parameterübergaben (<code>swServiceArg</code>, <code>swServiceReturn</code>), Datentypspezifikationen über <code>SwDataDefProps</code> und <code>SwBaseType</code> sowie die Konfiguration des Betriebssystems bezüglich Task- und ISR-Kontexten.</p>"}], "trans": [{"from": "FIG-4b2ddec02d2ed0a2", "to": "FIG-6cac80cfc422700c", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6cac80cfc422700c", "to": "FIG-9c77d80b64fcc564", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>BswModuleEntry</code>: Attributtyp von <code>serviceId</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>SwServiceProps</code>: Attribut <code>swServiceRecursive: String [0..1]</code> entfernt.</li>\n<li><code>SwClass::SwClass</code>: Klasse inklusive Assoziationen <code>+swClass</code> (0..1) und Rückbeziehung <code>+swDataDefProps</code> (0..1) zur Klasse <code>DataDefProperties::SwDataDefProps</code> vollständig entfernt.</li>\n<li><code>DataDefProperties::SwDataDefProps</code>: Attribute <code>swAliasName</code>, <code>swCalprmNoEffectValue</code>, <code>swIntendedResolution</code>, <code>swInterpolationMethod</code>, <code>swIsVirtual</code> und <code>swVarNotAvlValue</code> entfernt.</li>\n</ul>"}]};
